1	/**
2	 * #{#rsz1a} #{#rsz1b} - Receipt Image Resizing
3	 *
4	 * Resizes images before upload to optimize for Mistral OCR processing.
5	 * - Max dimension: 2000px on longest axis
6	 * - Compression: 85% quality
7	 * - Supports: JPEG, PNG
8	 */
9	
10	export interface ResizeDimensions {
11		width: number;
12		height: number;
13	}
14	
15	/**
16	 * #{#rsz1a} - Calculate resize dimensions maintaining aspect ratio
17	 *
18	 * Acceptance Criteria:
19	 * - Maximum dimension on longest axis must be 2000px
20	 * - Aspect ratio must be preserved during resize
21	 * - Images smaller than 2000px on longest axis keep original dimensions
22	 *
23	 * @param originalWidth - Original image width in pixels
24	 * @param originalHeight - Original image height in pixels
25	 * @param maxSize - Maximum dimension on longest axis (default: 2000)
26	 * @returns New dimensions with preserved aspect ratio
27	 */
28	export function calculateResizeDimensions(
29		originalWidth: number,
30		originalHeight: number,
31		maxSize: number = 2000
32	): ResizeDimensions {
33		const longestAxis = Math.max(originalWidth, originalHeight);
34	
35		// If image is already smaller than max, keep original dimensions
36		if (longestAxis <= maxSize) {
37			return { width: originalWidth, height: originalHeight };
38		}
39	
40		// Calculate scale factor
41		const scale = maxSize / longestAxis;
42	
43		// Calculate new dimensions (preserve aspect ratio)
44		return {
45			width: Math.round(originalWidth * scale),
46			height: Math.round(originalHeight * scale)
47		};
48	}
49	
50	/**
51	 * #{#rsz1a} #{#rsz1b} - Resize an image file using Canvas API
52	 *
53	 * Acceptance Criteria:
54	 * - Both JPEG and PNG formats must be resized
55	 * - Lossy compression at 85% quality must be applied
56	 * - Original filename extension must be preserved
57	 * - Resizing must occur client-side (browser) before upload
58	 * - Images smaller than 2000px still have compression applied
59	 * - EXIF orientation must be handled (#{#rsz2b})
60	 *
61	 * @param file - Original image file (JPEG or PNG)
62	 * @param maxSize - Maximum dimension on longest axis (default: 2000)
63	 * @param quality - Compression quality 0-1 (default: 0.85)
64	 * @returns Resized image file
65	 */
66	export async function resizeImage(
67		file: File,
68		maxSize: number = 2000,
69		quality: number = 0.85
70	): Promise<File> {
71		// Only resize JPEG and PNG
72		if (!['image/jpeg', 'image/png'].includes(file.type)) {
73			return file;
74		}
75	
76		return new Promise((resolve, reject) => {
77			const img = new Image();
78			const canvas = document.createElement('canvas');
79			const ctx = canvas.getContext('2d');
80	
81			if (!ctx) {
82				reject(new Error('Canvas context not available'));
83				return;
84			}
85	
86			img.onload = async () => {
87				try {
88					// #{#rsz2b} - Handle EXIF orientation using createImageBitmap
89					const bitmap = await createImageBitmap(file, {
90						imageOrientation: 'from-image'
91					});
92	
93					// Calculate new dimensions
94					const { width, height } = calculateResizeDimensions(bitmap.width, bitmap.height, maxSize);
95	
96					// Set canvas size
97					canvas.width = width;
98					canvas.height = height;
99	
100					// Draw resized image
101					ctx.drawImage(bitmap, 0, 0, width, height);
102	
103					// Convert to blob with compression
104					canvas.toBlob(
105						(blob) => {
106							if (!blob) {
107								reject(new Error('Failed to create blob'));
108								return;
109							}
110	
111							// #{#rsz3b} - Log resize metrics
112							const originalSize = file.size;
113							const resizedSize = blob.size;
114							const reduction = ((1 - resizedSize / originalSize) * 100).toFixed(1);
115	
116							console.log('Image resized:', {
117								originalSize: `${(originalSize / 1024).toFixed(2)}KB`,
118								resizedSize: `${(resizedSize / 1024).toFixed(2)}KB`,
119								reduction: `${reduction}%`,
120								originalDimensions: `${bitmap.width}x${bitmap.height}`,
121								resizedDimensions: `${width}x${height}`,
122								format: file.type
123							});
124	
125							// Create new File from blob
126							const resizedFile = new File([blob], file.name, {
127								type: file.type,
128								lastModified: Date.now()
129							});
130	
131							// Clean up
132							URL.revokeObjectURL(img.src);
133							bitmap.close();
134	
135							resolve(resizedFile);
136						},
137						file.type,
138						quality
139					);
140				} catch (error) {
141					URL.revokeObjectURL(img.src);
142					reject(error);
143				}
144			};
145	
146			img.onerror = () => {
147				URL.revokeObjectURL(img.src);
148				reject(new Error('Failed to load image'));
149			};
150	
151			// Load image
152			img.src = URL.createObjectURL(file);
153		});
154	}
