10	// Password requirements constants
11	export const MIN_PASSWORD_LENGTH = 16;
12	export const MIN_LENGTH_MESSAGE = `At least ${MIN_PASSWORD_LENGTH} characters`;
13	export const CHAR_TYPE_MESSAGE =
14		'At least one of: uppercase, lowercase, number, or special character';
15	
16	const UPPERCASE_REGEX = /[A-Z]/;
17	const LOWERCASE_REGEX = /[a-z]/;
18	const NUMBER_REGEX = /[0-9]/;
19	const SPECIAL_CHAR_REGEX = /[!@#$%^&*()_+\-=[\]{}|;:,.<>?]/;
20	
21	export function validatePassword(password: string): PasswordValidationResult {
22		const hasUppercase = UPPERCASE_REGEX.test(password);
23		const hasLowercase = LOWERCASE_REGEX.test(password);
24		const hasNumber = NUMBER_REGEX.test(password);
25		const hasSpecialChar = SPECIAL_CHAR_REGEX.test(password);
26	
27		const checks = {
28			minLength: password.length >= MIN_PASSWORD_LENGTH,
29			hasCharacterType: hasUppercase || hasLowercase || hasNumber || hasSpecialChar
30		};
31	
32		const errors: string[] = [];
33		if (!checks.minLength) errors.push(MIN_LENGTH_MESSAGE);
34		if (!checks.hasCharacterType) errors.push(CHAR_TYPE_MESSAGE);
35	
36		return {
37			isValid: Object.values(checks).every((check) => check),
38			errors,
39			checks
40		};
41	}
42	
43	export function passwordsMatch(password: string, confirmPassword: string): boolean {
44		return password === confirmPassword && password.length > 0;
45	}
