17	// #{#eaf1a} Supported MIME types for receipt attachments
18	export const SUPPORTED_RECEIPT_TYPES = new Set<string>([
19		'application/pdf',
20		'image/jpeg',
21		'image/png',
22		'image/heic'
23	]);
24	
25	// #{#eaf1a} Map file extensions to MIME types for fallback detection
26	export const EXTENSION_TO_MIME: Record<string, string> = {
27		pdf: 'application/pdf',
28		jpg: 'image/jpeg',
29		jpeg: 'image/jpeg',
30		png: 'image/png',
31		heic: 'image/heic'
32	};
33	
34	/**
35	 * #{#eaf1a} Check if an attachment has a supported receipt MIME type.
36	 * Falls back to file extension when content_type is missing or generic.
37	 */
38	export function isSupportedReceiptType(contentType: string, filename?: string): boolean {
39		const ct = contentType.toLowerCase().trim();
40	
41		if (SUPPORTED_RECEIPT_TYPES.has(ct)) {
42			return true;
43		}
44	
45		// Fall back to file extension when content_type is generic or empty
46		if (!ct || ct === 'application/octet-stream') {
47			if (!filename) return false;
48			const ext = filename.split('.').pop()?.toLowerCase();
49			if (!ext) return false;
50			return ext in EXTENSION_TO_MIME;
51		}
52	
53		return false;
54	}
55	
56	/**
57	 * #{#eaf2a} Check if an attachment is an inline image (signature, logo, tracking pixel).
58	 * Inline attachments have content_id set AND content_disposition containing "inline".
59	 */
60	export function isInlineAttachment(att: AttachmentMetadata): boolean {
61		return !!(
62			att.content_id &&
63			att.content_disposition?.toLowerCase().includes('inline')
64		);
65	}
66	
67	/**
68	 * #{#eaf3a} Check if OCR results contain usable data.
69	 * At least merchant_name or total_amount must be present.
70	 */
71	export function hasUsableOcrData(result: OcrResultData): boolean {
72		return result.merchant_name != null || result.total_amount != null;
73	}
74	
75	/**
76	 * #{#eaf5a} Check if webhook attachment metadata contains any supported receipt attachments.
77	 * Used to decide whether to prioritize attachments over body text.
78	 */
79	export function hasSupportedAttachments(attachments: AttachmentMetadata[]): boolean {
80		return attachments.some(
81			(att) => !isInlineAttachment(att) && isSupportedReceiptType(att.content_type, att.filename)
82		);
83	}
